package net.civeira.phylax.feature.access.userverificationcode.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.access.userverificationcode.domain.UserVerificationCode;
import net.civeira.phylax.feature.access.userverificationcode.domain.event.UserVerificationCodeEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class UserVerificationCodeEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<UserVerificationCodeEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final UserVerificationCode entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
